# Expanded autotune configs include num_stages=2 and num_stages=3
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 32},  num_warps=2, num_stages=1),
        triton.Config({'XBLOCK': 64},  num_warps=2, num_stages=1),
        triton.Config({'XBLOCK': 64},  num_warps=4, num_stages=2),
        triton.Config({'XBLOCK': 128}, num_warps=4, num_stages=2),
        triton.Config({'XBLOCK': 128}, num_warps=8, num_stages=2),
        triton.Config({'XBLOCK': 256}, num_warps=8, num_stages=3),
        # ... 16 configs spanning num_stages in {1, 2, 3}
    ],
    key=['xnumel'],
)
@triton.jit
def kernel(...):
    # large streaming matrix load — evict_first to avoid cache pollution
    val = tl.load(large_matrix_ptr + offset, mask=xmask, eviction_policy='evict_first')
